import logging
import os
import re
import time
from datetime import datetime

from taf.transport.ssh.connection import SSHConnection
from taf.transport.ssh.process import SSHProcess

from .exception import ParsingError, WrongResponseError


class GrepLineCounter:
    def count(self, out: str) -> int:
        """Method to count found lines in grep command output.

        :param str out:   Output from grep command.

        :return: Number of lines found by grep command.
        :rtype: int
        """
        result = 0
        for line in out.split("\n"):
            if self._is_multifile_regexp(line):
                number = self._find_number(line)
                result += self._convert_to_int(number)
            else:
                result += self._convert_to_int(line)
        return result

    def _is_multifile_regexp(self, data: str) -> bool:
        return ":" in data

    def _find_number(self, data: str) -> str:
        return data.split(":")[1].strip()

    def _convert_to_int(self, data: str) -> int:
        data = data.strip()
        if data:
            return int(data)
        return 0


class GrepCmdBuilder:
    def __init__(self, log_pattern: str):
        self._file_pattern = self._generate_file_pattern(log_pattern)

    def build_find_cmd(self, regexp: str) -> str:
        return f"grep -rnE '{regexp}' {self._file_pattern}"

    def build_count_cmd(self, regexp: str) -> str:
        return f"grep -cE '{regexp}' {self._file_pattern}"

    def _generate_file_pattern(self, log_pattern: str) -> str:
        if "*" not in log_pattern:
            return f"'{log_pattern}'"
        else:
            log_dir = os.path.dirname(log_pattern)
            file_pattern = os.path.basename(log_pattern)
            return f"'{log_dir}'/{file_pattern}"


class LogOperator:
    """Class to work with syslog file."""

    def __init__(self, log_pattern: str):
        """
        :param str      log_pattern:     Pattern to select all log files.
        """
        self._log_pattern = log_pattern
        self._ssh_connection = None
        self._counter = GrepLineCounter()
        self._builder = GrepCmdBuilder(log_pattern)
        self.logger = logging.getLogger(__name__)

    def connect(self, ssh_connection: SSHConnection) -> None:
        """Use given ssh_connection object for communication

        :param ssh_connection: existing SSH connection object
        :type ssh_connection: SSHConnection
        """
        self._ssh_connection = ssh_connection

    def message_exists(self, regexp: str) -> str:
        """Check if the specified message exists in the syslog file.

        :param str regexp: Pattern used to find the message in the syslog file.

        :raises: ParsingError when regexp cannot match any string.
        """
        find_command = self._builder.build_find_cmd(regexp)
        self.logger.debug(f"Executing command on remote host: {find_command}")
        process = self._send_command(find_command)
        out, err, rc = (
            process.read_output(),
            process.read_error(),
            process.get_exit_code(),
        )
        if err == "" and rc == 0:
            return out
        raise ParsingError(
            f"Cannot find any string to match regexp ({regexp}) in file ({self._log_pattern})"
        )

    def wait_for_message(
        self, regexp: str, timeout: float, interval: float = 0.5
    ) -> str:
        """Wait for the specified message to appear in the syslog file.

        :param str    regexp:   Pattern used to find the message in the syslog file.
        :param float  timeout:  Max. time to wait for message to appear, in seconds.
        :param float  interval: Interval between ssh grep requests.

        :return: Output from grep command.
        :rtype: str

        :raises: ParsingError when regexp cannot match any string.
        """
        start_time = time.time()
        command = self._builder.build_find_cmd(regexp)
        self.logger.debug(f"Executing command in a loop on remote host: {command}")
        while time.time() - start_time < timeout:
            process = self._send_command(command)
            out, err, rc = (
                process.read_output(),
                process.read_error(),
                process.get_exit_code(),
            )
            if err == "" and rc == 0:
                return out
            time.sleep(interval)
        raise ParsingError(
            f"Cannot find any string matching regexp ({regexp}) in file ({self._log_pattern})"
        )

    def count_messages(self, regexp: str) -> int:
        """Return number of found messages in log file.

        :param str regexp: Pattern used to find the message in the syslog file.

        :return: Returns the number of found messages in the log file.
        :rtype: int

        :raises: WrongResponseError if output format from executed command is wrong.
        """
        count_command = self._builder.build_count_cmd(regexp)
        self.logger.debug(f"Executing command on remote host: {count_command}")
        process = self._send_command(count_command)
        out, rc = process.read_output(), process.get_exit_code()
        try:
            return self._counter.count(out)
        except ValueError as e:
            raise WrongResponseError(
                f"Cannot count messages for regexp ({regexp}) and file ({self._log_pattern})\n",
                out,
                rc,
                e,
            )

    def message_exists_from_savepoint(self, regexp: str, savepoint: str):
        """Find the first message after the savepoint in the log file."""
        all_messages = self.message_exists(regexp)
        savepoint_timestamp = self._parse_datetimestr_to_datetime(savepoint)
        self.logger.debug(f"Searching for message after savepoint {savepoint}")
        for message in all_messages.split("\n"):
            if message == "":
                continue
            timestamp_string = self._get_datetime_string_from_message(message)
            message_timestamp = self._parse_datetimestr_to_datetime(timestamp_string)
            if message_timestamp > savepoint_timestamp:
                return message
        raise ParsingError(
            f"Cannot find any message after savepoint at {savepoint} in file {self._log_pattern}"
        )

    def get_timestamp_of_last_line(self, log_path: str) -> str:
        cmd = f"tail -n1 {log_path}"
        process = self._send_command(cmd)
        output = process.read_output()
        return self._get_datetime_string_from_message(output)

    def _send_command(self, command: str) -> SSHProcess:
        return self._ssh_connection.send_command(command)

    @staticmethod
    def _get_datetime_string_from_message(message: str) -> str:
        # Example input:
        # '77575:17.05 09:47:33.099999 [127.0.0.1] Message content'
        # Example output:
        # '17.05 09:47:33.099999'
        datetime_regex = r"(0[1-9]|[12][0-9]|3[01])\.(0[1-9]|1[0-2]) (0[0-9]|1[0-9]|2[0-3]):(0[0-9]|[1-5][0-9]):(0[0-9]|[1-5][0-9])\.\d{6}"
        datetime_string = re.search(datetime_regex, message)
        return datetime_string.group()

    @staticmethod
    def _parse_datetimestr_to_datetime(datetime_string: str) -> datetime:
        split_datetime = [
            int(item) for item in re.split(r"[ .:]", datetime_string.strip())
        ]
        day, month, hour, minute, second, microsecond = split_datetime
        return datetime(
            year=datetime.now().year,  # The year does not matter, set it to a constant for comparison
            month=month,
            day=day,
            hour=hour,
            minute=minute,
            second=second,
            microsecond=microsecond,
        )
